class LoginScreenState extends State<LoginScreen>{ final emailC=TextEditingController(); final passC=TextEditingController(); String err=''; bool load=false; void doLogin() async { if(emailC.text.trim().isEmpty||passC.text.isEmpty){ setState(()=>err='Enter email and password'); return; } setState(()=>load=true); final p=await SharedPreferences.getInstance(); final email=emailC.text.trim().toLowerCase(); bool isAdmin=email=='mugabibenjamin14@gmail.com'&&passC.text=='Mugabibe+-@1'; await p.setString('registered_email_permanent',email); await p.setBool('is_logged_in',true); await p.setBool('is_admin',isAdmin); if(mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder:(_)=>MainNav(email:email,isAdmin:isAdmin,onTheme:widget.onTheme))); setState(()=>load=false); } @override Widget build(BuildContext c)=>Scaffold(backgroundColor:Colors.black, body:Center(child:SingleChildScrollView(padding:EdgeInsets.all(24), child:Column(mainAxisAlignment:MainAxisAlignment.center, children:[Icon(Icons.movie_filter,size:70,color:Colors.orange), SizedBox(height:10), Text('ONYX MOVIES',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold,color:Colors.orange)), SizedBox(height:30), TextField(controller:emailC,style:TextStyle(color:Colors.white),decoration:InputDecoration(labelText:'Email',filled:true,fillColor:Colors.grey[900],border:OutlineInputBorder())), SizedBox(height:12), TextField(controller:passC,obscureText:true,style:TextStyle(color:Colors.white),decoration:InputDecoration(labelText:'Password',filled:true,fillColor:Colors.grey[900],border:OutlineInputBorder())), SizedBox(height:12), if(err.isNotEmpty) Text(err,style:TextStyle(color:Colors.red)), SizedBox(height:20), SizedBox(width:double.infinity,height:50, child:ElevatedButton(onPressed:load?null:doLogin,style:ElevatedButton.styleFrom(backgroundColor:Colors.orange), child:load?IPhoneLoader():Text('LOGIN',style:TextStyle(color:Colors.white))))])))); }
class PasscodeLock extends StatefulWidget{ final String email; final bool isAdmin; final VoidCallback onTheme; const PasscodeLock({super.key,required this.email,required this.isAdmin,required this.onTheme}); @override State<PasscodeLock> createState()=>PasscodeLockState(); }
class PasscodeLockState extends State<PasscodeLock>{ String entered=''; final LocalAuthentication auth=LocalAuthentication(); @override void initState(){ super.initState(); tryBio(); } tryBio() async { final p=await SharedPreferences.getInstance(); final useBio=p.getBool('use_biometric')??false; if(useBio){ try{ final ok=await auth.authenticate(localizedReason:'Unlock Onyx Movies'); if(ok && mounted){ Navigator.pushReplacement(context, MaterialPageRoute(builder:(_)=>MainNav(email:widget.email,isAdmin:widget.isAdmin,onTheme:widget.onTheme))); } } catch(e){} } } onNum(String n) async { if(entered.length<6){ setState(()=>entered+=n); } if(entered.length==6){ final p=await SharedPreferences.getInstance(); final saved=p.getString('app_passcode'); if(entered==saved){ if(mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder:(_)=>MainNav(email:widget.email,isAdmin:widget.isAdmin,onTheme:widget.onTheme))); } else { setState(()=>entered=''); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Wrong passcode'))); } } } @override Widget build(BuildContext c)=>Scaffold(backgroundColor:Colors.black, body:Column(mainAxisAlignment:MainAxisAlignment.center, children:[ Icon(Icons.lock,size:60,color:Colors.orange), SizedBox(height:10), Text('Enter 6-digit passcode',style:TextStyle(color:Colors.white)), SizedBox(height:20), Row(mainAxisAlignment:MainAxisAlignment.center, children: List.generate(6, (i)=>Container(margin:EdgeInsets.all(6),width:16,height:16,decoration:BoxDecoration(shape:BoxShape.circle,color: i<entered.length?Colors.orange:Colors.white24)))), SizedBox(height:30), GridView.builder(shrinkWrap:true, padding:EdgeInsets.symmetric(horizontal:60), gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,mainAxisSpacing:20,crossAxisSpacing:20), itemCount:12, itemBuilder:(c,i){ if(i==9) return IconButton(onPressed:tryBio, icon:Icon(Icons.fingerprint,color:Colors.orange)); if(i==10) return ElevatedButton(onPressed:()=>onNum('0'), style:ElevatedButton.styleFrom(shape:CircleBorder(),backgroundColor:Color(0xFF1E1E1E)), child:Text('0',style:TextStyle(color:Colors.white,fontSize:22))); if(i==11) return IconButton(onPressed:()=>setState(()=>entered=entered.isNotEmpty?entered.substring(0,entered.length-1):''), icon:Icon(Icons.backspace,color:Colors.white)); final num='${i+1}'; return ElevatedButton(onPressed:()=>onNum(num), style:ElevatedButton.styleFrom(shape:CircleBorder(),backgroundColor:Color(0xFF1E1E1E)), child:Text(num,style:TextStyle(color:Colors.white,fontSize:22))); }) ])); }
