class HomeFull extends StatefulWidget{ final String email; final bool isAdmin; const HomeFull({super.key,required this.email,required this.isAdmin}); @override State<HomeFull> createState()=>HomeFullState(); }
class HomeFullState extends State<HomeFull>{
  final ref=FirebaseDatabase.instance.ref('movies');
  final refVj=FirebaseDatabase.instance.ref('settings/vj_names');
  final refGenres=FirebaseDatabase.instance.ref('settings/genres');
  List<String> vjList=['All']; List<String> genreList=['All']; List<String> favIds=[];
  static const String currentVersion="1.1.0";
  @override void initState(){ super.initState(); loadCats(); loadFav(); checkForUpdate(); }
  checkForUpdate() async {
    await Future.delayed(Duration(seconds:3));
    try{
      final snap=await FirebaseDatabase.instance.ref('settings/app_update').get();
      if(snap.value!=null){
        final data=Map<String,dynamic>.from(snap.value as Map);
        final latest=data['latestVersion']?.toString()??'';
        final apkUrl=data['apkUrl']?.toString()??'';
        final whatsNew=data['whatsNew']?.toString()??'New features and bug fixes!';
        final force=data['forceUpdate']??false;
        if(latest.isNotEmpty && latest!=currentVersion){
          if(mounted){
            showDialog(context:context, barrierDismissible:!force, builder:(c)=>AlertDialog(
              backgroundColor:Color(0xFF1E293B),
              shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(16)),
              title:Row(children:[Icon(Icons.system_update,color:Colors.orange), SizedBox(width:8), Text('Update Available!',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold))]),
              content:Column(mainAxisSize:MainAxisSize.min, crossAxisAlignment:CrossAxisAlignment.start, children:[
                Container(padding:EdgeInsets.symmetric(horizontal:10,vertical:4), decoration:BoxDecoration(color:Colors.orange,borderRadius:BorderRadius.circular(20)), child:Text('v$latest',style:TextStyle(color:Colors.white,fontSize:11,fontWeight:FontWeight.bold))),
                SizedBox(height:10),
                Text('Current: v$currentVersion',style:TextStyle(color:Colors.white38,fontSize:11)),
                SizedBox(height:8),
                Text(whatsNew,style:TextStyle(color:Colors.white70,fontSize:12)),
                SizedBox(height:12),
                if(force) Container(padding:EdgeInsets.all(8), decoration:BoxDecoration(color:Colors.red.withOpacity(0.2),borderRadius:BorderRadius.circular(8)), child:Row(children:[Icon(Icons.warning,color:Colors.red,size:14), SizedBox(width:6), Expanded(child:Text('This update is required!',style:TextStyle(color:Colors.red,fontSize:10)))]))
              ]),
              actions:[
                if(!force) TextButton(onPressed:()=>Navigator.pop(context), child:Text('Later',style:TextStyle(color:Colors.white54))),
                ElevatedButton.icon(onPressed:() async { if(apkUrl.isNotEmpty){ final uri=Uri.parse(apkUrl); if(await canLaunchUrl(uri)){ await launchUrl(uri,mode:LaunchMode.externalApplication); } } }, icon:Icon(Icons.download,color:Colors.white,size:16), label:Text('UPDATE NOW',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold)), style:ElevatedButton.styleFrom(backgroundColor:Colors.orange,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(8))))
              ],
            ));
          }
        }
      }
    } catch(e){}
  }
  loadCats() async {
    try{ final s1=await refVj.get(); if(s1.value!=null){ final m=Map<String,dynamic>.from(s1.value as Map); setState(()=>vjList=['All',...m.values.map((e)=>e.toString())]); } } catch(e){}
    try{ final s2=await refGenres.get(); if(s2.value!=null){ final m=Map<String,dynamic>.from(s2.value as Map); setState(()=>genreList=['All',...m.values.map((e)=>e.toString())]); } } catch(e){}
  }
  loadFav() async { final p=await SharedPreferences.getInstance(); setState(()=>favIds=p.getStringList('favs')??[]); }
  toggleFav(String id) async { final p=await SharedPreferences.getInstance(); if(favIds.contains(id)) favIds.remove(id); else favIds.add(id); await p.setStringList('favs', favIds); setState((){}); }
  openSearch() {
    showModalBottomSheet(context:context, backgroundColor:Color(0xFF0F172A), shape:RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(20))), builder:(c){
      String selVj='All'; String selGenre='All';
      return StatefulBuilder(builder:(c,setM){
        return Padding(padding:EdgeInsets.all(16), child:ListView(children:[
          Text('Search by Category',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:16)),
          SizedBox(height:12), Text('VJ',style:TextStyle(color:Colors.white70)), Wrap(spacing:6, children:vjList.map((v)=>ChoiceChip(label:Text(v,style:TextStyle(fontSize:11)),selected:selVj==v,selectedColor:Colors.orange,onSelected:(s){ setM(()=>selVj=v); Navigator.pop(context); Navigator.push(context, MaterialPageRoute(builder:(_)=>FilterPage(vj:selVj,genre:selGenre))); })).toList()),
          SizedBox(height:12), Text('Genre',style:TextStyle(color:Colors.white70)), Wrap(spacing:6, children:genreList.map((g)=>ChoiceChip(label:Text(g,style:TextStyle(fontSize:11)),selected:selGenre==g,selectedColor:Colors.orange,onSelected:(s){ setM(()=>selGenre=g); Navigator.pop(context); Navigator.push(context, MaterialPageRoute(builder:(_)=>FilterPage(vj:selVj,genre:g))); })).toList()),
        ]));
      });
    });
  }
  Widget section(String title, List<MapEntry<String, dynamic>> items){
    if(items.isEmpty) return SizedBox();
    return Column(crossAxisAlignment:CrossAxisAlignment.start, children:[
      Padding(padding:EdgeInsets.symmetric(horizontal:12,vertical:8), child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween, children:[Text(title,style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:16)), TextButton(onPressed:()=>Navigator.push(context, MaterialPageRoute(builder:(_)=>SeeMorePage(title:title,items:items))), child:Text('See More',style:TextStyle(color:Colors.orange,fontSize:12)))])),
      SizedBox(height:135, child:ListView.builder(scrollDirection:Axis.horizontal, padding:EdgeInsets.symmetric(horizontal:12), itemCount:items.length, itemBuilder:(c,i){
        final m=Map<String,dynamic>.from(items[i].value as Map);
        final isFav=favIds.contains(items[i].key);
        return GestureDetector(onTap:()=>Navigator.push(c, MaterialPageRoute(builder:(_)=>PlayerPage(movie:m,id:items[i].key,onFav:(){ toggleFav(items[i].key); },isFav:isFav))), child:Container(width:110, margin:EdgeInsets.only(right:8), child:Column(children:[Expanded(child:Stack(children:[SafePoster(base64Str:m['posterBase64']??'',vjCorner:m['vj']??''), if(isFav) Positioned(top:4,left:4, child:Icon(Icons.favorite,size:14,color:Colors.red))])), SizedBox(height:4), Text(m['title']??'',style:TextStyle(color:Colors.white,fontSize:10),maxLines:1,overflow:TextOverflow.ellipsis)])));
      }))
    ]);
  }
  @override Widget build(BuildContext c){
    return SafeArea(child: CustomScrollView(slivers:[
      SliverToBoxAdapter(child: LiquidSearchBar(onTap:openSearch,onNotif:(){ ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('🔔 No new notifications'))); },onDownload:(){})),
      SliverToBoxAdapter(child: StreamBuilder(stream:ref.orderByChild('timestamp').limitToLast(7).onValue, builder:(c,snap){
        if(!snap.hasData||snap.data!.snapshot.value==null) return Container(height:220,margin:EdgeInsets.all(12), decoration:BoxDecoration(color:Color(0xFF1E293B),borderRadius:BorderRadius.circular(16)), child:Center(child:IPhoneLoader()));
        final map=Map<String,dynamic>.from(snap.data!.snapshot.value as Map);
        final list=map.entries.toList()..sort((a,b){ final at=Map<String,dynamic>.from(a.value as Map)['timestamp']??0; final bt=Map<String,dynamic>.from(b.value as Map)['timestamp']??0; return bt.compareTo(at); });
        return SizedBox(height:260, child:PageView.builder(itemCount:list.length, itemBuilder:(c,i){
          final m=Map<String,dynamic>.from(list[i].value as Map);
          final isFav=favIds.contains(list[i].key);
          return GestureDetector(onTap:()=>Navigator.push(c, MaterialPageRoute(builder:(_)=>PlayerPage(movie:m,id:list[i].key,onFav:(){ toggleFav(list[i].key); },isFav:isFav))), child:Container(margin:EdgeInsets.all(12), decoration:BoxDecoration(borderRadius:BorderRadius.circular(16), color:Color(0xFF1E293B)), child:ClipRRect(borderRadius:BorderRadius.circular(16), child:Stack(fit:StackFit.expand, children:[
            SafePoster(base64Str:m['posterBase64']??''),
            Container(decoration:BoxDecoration(gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Colors.transparent,Colors.black.withOpacity(0.85)]))),
            Positioned(bottom:12,left:12,right:12, child:Column(crossAxisAlignment:CrossAxisAlignment.start, children:[
              Row(children:[Container(padding:EdgeInsets.symmetric(horizontal:6,vertical:2), decoration:BoxDecoration(color:Colors.orange,borderRadius:BorderRadius.circular(4)), child:Text(m['genre']??'Action',style:TextStyle(color:Colors.white,fontSize:9))), SizedBox(width:6), Text(m['year']??'2024',style:TextStyle(color:Colors.white70,fontSize:10)), Spacer(), IconButton(icon:Icon(isFav?Icons.favorite:Icons.favorite_border,color:isFav?Colors.red:Colors.white,size:20), onPressed:(){ toggleFav(list[i].key); })]),
              Text(m['title']??'',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:17)),
              Text(m['description']??'',maxLines:2,overflow:TextOverflow.ellipsis,style:TextStyle(color:Colors.white70,fontSize:11)),
            ]))
          ]))));
        }));
      })),
      SliverToBoxAdapter(child: StreamBuilder(stream:ref.onValue, builder:(c,snap){
        if(!snap.hasData||snap.data!.snapshot.value==null) return Center(child:IPhoneLoader());
        final map=Map<String,dynamic>.from(snap.data!.snapshot.value as Map);
        var all=map.entries.toList()..sort((a,b){ final at=Map<String,dynamic>.from(a.value as Map)['timestamp']??0; final bt=Map<String,dynamic>.from(b.value as Map)['timestamp']??0; return bt.compareTo(at); });
        var movies=all.where((e){ final m=Map<String,dynamic>.from(e.value as Map); return (m['type']??'movie')!='series'; }).toList();
        var series=all.where((e){ final m=Map<String,dynamic>.from(e.value as Map); return m['type']=='series'; }).toList();
        var anim=movies.where((e){ final m=Map<String,dynamic>.from(e.value as Map); return (m['genre']??'').toString().toLowerCase().contains('anim'); }).toList();
        var indian=movies.where((e){ final m=Map<String,dynamic>.from(e.value as Map); return (m['genre']??'').toString().toLowerCase().contains('indian')||(m['category']??'').toString().toLowerCase().contains('indian'); }).toList();
        var trending=movies.take(10).toList();
        return Column(children:[
          section('🔥 Latest Release', movies),
          section('📺 Latest Series', series),
          section('⭐ Trending Movies', trending),
          section('🎨 Animations', anim.isEmpty?movies.take(5).toList():anim),
          section('🇮🇳 Indian Movies', indian.isEmpty?movies.take(5).toList():indian),
          SizedBox(height:20),
        ]);
      }))
    ]));
  }
}
