class PlayerPageState extends State<PlayerPage>{
  VideoPlayerController? ctrl; bool isDownloading=false; double dlProgress=0;
  @override void initState(){ super.initState(); initVideo(); }
  initVideo(){ final url=widget.movie['downloadUrl']?.toString(); if(url!=null&&url.startsWith('http')){ try{ ctrl=VideoPlayerController.networkUrl(Uri.parse(url))..initialize().then((_)=>setState((){})); } catch(e){} } }
  downloadFile() async {
    try{
      await Permission.storage.request();
      final url=widget.movie['downloadUrl']?.toString();
      if(url==null||url.isEmpty){ ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('No download URL'))); return; }
      setState(()=>isDownloading=true);
      final dir=await getExternalStorageDirectory();
      final folder=Directory('${dir!.path}/OnyxMovies');
      if(!await folder.exists()) await folder.create(recursive:true);
      final savePath='${folder.path}/${widget.movie['title']??'movie'}.mp4';
      final dio=Dio();
      await dio.download(url, savePath, onReceiveProgress:(rec,total){ if(total!=-1) setState(()=>dlProgress=rec/total); });
      final p=await SharedPreferences.getInstance();
      final list=p.getStringList('downloaded_files')??[];
      list.add(savePath);
      await p.setStringList('downloaded_files', list);
      setState(()=>isDownloading=false);
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('✅ Downloaded'),backgroundColor:Colors.green));
    } catch(e){
      setState(()=>isDownloading=false);
      try{ final uri=Uri.parse(widget.movie['downloadUrl']); if(await canLaunchUrl(uri)) await launchUrl(uri,mode:LaunchMode.externalApplication); } catch(_){}
    }
  }
  shareMovie(){ final title=widget.movie['title']??'Movie'; final url=widget.movie['downloadUrl']??''; Share.share('🎬 Watch $title on ONYX MOVIES App\n\nLink: $url\n\nDownload Onyx Movies App!'); }
  @override void dispose(){ ctrl?.dispose(); super.dispose(); }
  @override Widget build(BuildContext c){
    final casts=widget.movie['casts']!=null? List.from(widget.movie['casts']) : [];
    final eps=widget.movie['episodes']!=null? List.from(widget.movie['episodes']) : [];
    return Scaffold(backgroundColor:Colors.black, appBar:AppBar(backgroundColor:Colors.black, title:Text(widget.movie['title']??'',style:TextStyle(fontSize:14)), actions:[IconButton(icon:Icon(Icons.share,color:Colors.white), onPressed:shareMovie), IconButton(icon:Icon(widget.isFav?Icons.favorite:Icons.favorite_border,color:widget.isFav?Colors.red:Colors.white), onPressed:widget.onFav)]),
      body: ListView(padding:EdgeInsets.all(12), children:[
        AspectRatio(aspectRatio:16/9, child:Stack(children:[
          Container(decoration:BoxDecoration(color:Color(0xFF1E1E1E),borderRadius:BorderRadius.circular(12)), child: ctrl!=null && ctrl!.value.isInitialized? ClipRRect(borderRadius:BorderRadius.circular(12), child:VideoPlayer(ctrl!)) : Center(child:SafePoster(base64Str:widget.movie['posterBase64']??''))),
          Positioned.fill(child:Center(child:IconButton(icon:Icon(Icons.play_circle_fill,size:70,color:Colors.orange.withOpacity(0.9)), onPressed:(){ if(ctrl!=null){ if(ctrl!.value.isPlaying) ctrl!.pause(); else ctrl!.play(); setState((){}); } else { downloadFile(); } }))),
        ])),
        SizedBox(height:12),
        Row(children:[
          Expanded(child:ElevatedButton.icon(onPressed:isDownloading?null:downloadFile, icon:Icon(Icons.download), label:Text(isDownloading?'${(dlProgress*100).toStringAsFixed(0)}%':'Download'), style:ElevatedButton.styleFrom(backgroundColor:Colors.orange,padding:EdgeInsets.symmetric(vertical:14)))),
          SizedBox(width:8),
          ElevatedButton.icon(onPressed:(){ final url=widget.movie['downloadUrl']; if(url!=null){ final uri=Uri.parse(url); launchUrl(uri,mode:LaunchMode.externalApplication); } }, icon:Icon(Icons.play_arrow), label:Text('Play'), style:ElevatedButton.styleFrom(backgroundColor:Color(0xFF1E293B),padding:EdgeInsets.symmetric(vertical:14,horizontal:20))),
          SizedBox(width:8),
          ElevatedButton(onPressed:shareMovie, style:ElevatedButton.styleFrom(backgroundColor:Color(0xFF1E293B),padding:EdgeInsets.symmetric(vertical:14)), child:Icon(Icons.share,color:Colors.white))
        ]),
        if(isDownloading) Padding(padding:EdgeInsets.only(top:8), child:LinearProgressIndicator(value:dlProgress,color:Colors.orange,backgroundColor:Colors.white24)),
        SizedBox(height:14),
        Text(widget.movie['title']??'',style:TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.bold)),
        SizedBox(height:4),
        Row(children:[Container(padding:EdgeInsets.symmetric(horizontal:8,vertical:3), decoration:BoxDecoration(color:Colors.orange,borderRadius:BorderRadius.circular(4)), child:Text(widget.movie['genre']??'Action',style:TextStyle(color:Colors.white,fontSize:10,fontWeight:FontWeight.bold))), SizedBox(width:8), Text('VJ: ${widget.movie['vj']??''}',style:TextStyle(color:Colors.white54,fontSize:12)), SizedBox(width:8), Text('${widget.movie['year']??''}',style:TextStyle(color:Colors.white54,fontSize:12))]),
        SizedBox(height:10),
        Text(widget.movie['description']??'No description',style:TextStyle(color:Colors.white70,fontSize:13,height:1.4)),
        SizedBox(height:16),
        if(casts.isNotEmpty)...[Text('🎭 Casts',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:15)), SizedBox(height:8), SizedBox(height:85, child:ListView.builder(scrollDirection:Axis.horizontal, itemCount:casts.length, itemBuilder:(c,i){ final cast=Map<String,dynamic>.from(casts[i] as Map); return Container(width:65,margin:EdgeInsets.only(right:10), child:Column(children:[CircleAvatar(radius:28, backgroundColor:Color(0xFF1E293B), backgroundImage: cast['photoBase64']!=null && cast['photoBase64'].toString().length>20? MemoryImage(base64Decode(cast['photoBase64'])) : null, child: cast['photoBase64']==null||cast['photoBase64'].toString().length<20?Icon(Icons.person,color:Colors.white54):null), SizedBox(height:5), Text(cast['name']??'',style:TextStyle(color:Colors.white,fontSize:9),maxLines:1,overflow:TextOverflow.ellipsis,textAlign:TextAlign.center)])); }))],
        if(eps.isNotEmpty)...[SizedBox(height:18), Text('📺 Episodes (${eps.length})',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:15)), SizedBox(height:8),...eps.asMap().entries.map((e){ final ep=Map<String,dynamic>.from(e.value as Map); return Card(color:Color(0xFF1E293B), shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(10)), child:ListTile(leading:Container(width:36,height:36, decoration:BoxDecoration(color:Colors.orange,borderRadius:BorderRadius.circular(8)), child:Center(child:Text('${e.key+1}',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold)))), title:Text(ep['title']??'Episode ${e.key+1}',style:TextStyle(color:Colors.white,fontSize:13)), subtitle:Text('Tap to play',style:TextStyle(color:Colors.white38,fontSize:9)), trailing:Row(mainAxisSize:MainAxisSize.min, children:[IconButton(icon:Icon(Icons.play_arrow,color:Colors.orange), onPressed:() async { final u=ep['url']??''; if(u.isNotEmpty){ final uri=Uri.parse(u); if(await canLaunchUrl(uri)) await launchUrl(uri,mode:LaunchMode.externalApplication); } })]))); })]
      ]),
    );
  }
}
