class AdminSettingsFullState extends State<AdminSettingsFull>{
  final vjC=TextEditingController(); final genreC=TextEditingController();
  final verC=TextEditingController(); final urlC=TextEditingController(); final whatsC=TextEditingController();
  final refVj=FirebaseDatabase.instance.ref('settings/vj_names'); final refGenre=FirebaseDatabase.instance.ref('settings/genres');
  final refUpdate=FirebaseDatabase.instance.ref('settings/app_update');
  bool forceUpdate=false;
  addVj() async { if(vjC.text.isEmpty) return; await refVj.push().set(vjC.text); vjC.clear(); }
  addGenre() async { if(genreC.text.isEmpty) return; await refGenre.push().set(genreC.text); genreC.clear(); }
  saveUpdate() async {
    if(verC.text.isEmpty||urlC.text.isEmpty){ ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Version + APK URL required'))); return; }
    await refUpdate.set({'latestVersion':verC.text.trim(),'apkUrl':urlC.text.trim(),'whatsNew':whatsC.text.trim().isEmpty?'Bug fixes and improvements':whatsC.text.trim(),'forceUpdate':forceUpdate,'timestamp':ServerValue.timestamp});
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('✅ Update published! All users will see popup'),backgroundColor:Colors.green));
    verC.clear(); urlC.clear(); whatsC.clear();
  }
  @override Widget build(BuildContext c){
    return ListView(padding:EdgeInsets.all(12), children:[
      Text('Settings + Auto Update',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:15)),
      SizedBox(height:12),
      Card(color:Color(0xFF1E293B), shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(12)), child:Padding(padding:EdgeInsets.all(12), child:Column(crossAxisAlignment:CrossAxisAlignment.start, children:[
        Row(children:[Icon(Icons.system_update,color:Colors.green,size:18), SizedBox(width:6), Text('🚀 App Auto Update Manager',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold))]),
        SizedBox(height:4), Text('When you publish new APK, users get popup',style:TextStyle(color:Colors.white38,fontSize:10)),
        SizedBox(height:12),
        TextField(controller:verC,style:TextStyle(color:Colors.white,fontSize:13),decoration:InputDecoration(labelText:'Latest Version e.g. 1.1.1',isDense:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(8)),prefixIcon:Icon(Icons.tag,color:Colors.orange))),
        SizedBox(height:8),
        TextField(controller:urlC,style:TextStyle(color:Colors.white,fontSize:13),decoration:InputDecoration(labelText:'APK Download Link (https://...)',isDense:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(8)),prefixIcon:Icon(Icons.link,color:Colors.blue))),
        SizedBox(height:8),
        TextField(controller:whatsC,maxLines:2,style:TextStyle(color:Colors.white,fontSize:13),decoration:InputDecoration(labelText:'What is New? (changelog)',isDense:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(8)),prefixIcon:Icon(Icons.new_releases,color:Colors.green))),
        SizedBox(height:8),
        Row(children:[Text('Force Update (must update)?',style:TextStyle(color:Colors.white70,fontSize:12)), Spacer(), Switch(value:forceUpdate,activeColor:Colors.red,onChanged:(v)=>setState(()=>forceUpdate=v))]),
        SizedBox(height:12),
        SizedBox(width:double.infinity,height:48, child:ElevatedButton.icon(onPressed:saveUpdate, icon:Icon(Icons.cloud_upload,color:Colors.white), label:Text('PUBLISH UPDATE TO ALL USERS',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:12)), style:ElevatedButton.styleFrom(backgroundColor:Colors.green,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(10))))),
        SizedBox(height:8),
        StreamBuilder(stream:refUpdate.onValue, builder:(c,snap){ if(!snap.hasData||snap.data!.snapshot.value==null) return Text('No update published yet',style:TextStyle(color:Colors.white38,fontSize:11)); final data=Map<String,dynamic>.from(snap.data!.snapshot.value as Map); return Container(padding:EdgeInsets.all(10), decoration:BoxDecoration(color:Color(0xFF0F172A),borderRadius:BorderRadius.circular(8),border:Border.all(color:Colors.green.withOpacity(0.3))), child:Column(crossAxisAlignment:CrossAxisAlignment.start, children:[Text('Current Live Update:',style:TextStyle(color:Colors.green,fontSize:10,fontWeight:FontWeight.bold)), SizedBox(height:4), Text('Version: ${data['latestVersion']}',style:TextStyle(color:Colors.white,fontSize:12)), Text('URL: ${data['apkUrl']}',style:TextStyle(color:Colors.white54,fontSize:9),maxLines:1,overflow:TextOverflow.ellipsis), Text('Force: ${data['forceUpdate']}',style:TextStyle(color:Colors.white38,fontSize:10))])) ; }),
      ]))),
      SizedBox(height:12),
      Text('VJ Names',style:TextStyle(color:Colors.white70)), Row(children:[Expanded(child:TextField(controller:vjC,style:TextStyle(color:Colors.white),decoration:InputDecoration(labelText:'New VJ',border:OutlineInputBorder()))), IconButton(onPressed:addVj, icon:Icon(Icons.add,color:Colors.orange))]),
      StreamBuilder(stream:refVj.onValue, builder:(c,snap){ if(!snap.hasData||snap.data!.snapshot.value==null) return Text('No VJs',style:TextStyle(color:Colors.white54)); final map=Map<String,dynamic>.from(snap.data!.snapshot.value as Map); final list=map.entries.toList(); return Wrap(spacing:6, children:list.map((e)=>Chip(label:Text(e.value.toString(),style:TextStyle(fontSize:10)), onDeleted:() async { await refVj.child(e.key).remove(); })).toList()); }),
      SizedBox(height:16),
      Text('Genres',style:TextStyle(color:Colors.white70)), Row(children:[Expanded(child:TextField(controller:genreC,style:TextStyle(color:Colors.white),decoration:InputDecoration(labelText:'New Genre',border:OutlineInputBorder()))), IconButton(onPressed:addGenre, icon:Icon(Icons.add,color:Colors.orange))]),
      StreamBuilder(stream:refGenre.onValue, builder:(c,snap){ if(!snap.hasData||snap.data!.snapshot.value==null) return Text('No Genres',style:TextStyle(color:Colors.white54)); final map=Map<String,dynamic>.from(snap.data!.snapshot.value as Map); final list=map.entries.toList(); return Wrap(spacing:6, children:list.map((e)=>Chip(label:Text(e.value.toString(),style:TextStyle(fontSize:10)), onDeleted:() async { await refGenre.child(e.key).remove(); })).toList()); }),
    ]);
  }
